-- =====================================================================
--  MIGRACION DE CATALOGO E INVENTARIO INICIAL - EL PISINGO
--  Origen : Inventario_consolidado_El_Pisingo_programa.xlsx
--  Filas  : 1998 productos - 8 categorias
--
--  Crea categorias, productos, existencias y el movimiento de kardex
--  del saldo inicial. Es IDEMPOTENTE: si se corre dos veces no duplica
--  nada (llave: empresa_id + sku para producto, empresa_id + nombre
--  para categoria).
--
--  ANTES DE EJECUTAR: llenar los valores del bloque PARAMETROS.
-- =====================================================================

BEGIN;

-- ---------------------------------------------------------------------
--  0. PARAMETROS - EDITAR ESTOS VALORES Y NADA MAS
-- ---------------------------------------------------------------------
CREATE TEMP TABLE _p ON COMMIT DROP AS
SELECT
    17::bigint    AS empresa_id,      -- id de la empresa El Pisingo
    16::bigint    AS sucursal_id,     -- id de la sucursal donde queda el stock
    -- las unidades se resuelven por nombre/abreviatura (unidad_medida es global)
    (SELECT id FROM unidad_medida
      WHERE deleted_at IS NULL
        AND (UPPER(TRIM(COALESCE(abreviatura,''))) IN ('UND','UN','U','UNI')
          OR UPPER(TRIM(COALESCE(nombre,'')))      IN ('UNIDAD','UNIDADES'))
      ORDER BY id LIMIT 1)::bigint    AS und_id,
    (SELECT id FROM unidad_medida
      WHERE deleted_at IS NULL
        AND (UPPER(TRIM(COALESCE(abreviatura,''))) IN ('M','MT','MTS','MTR','METRO')
          OR UPPER(TRIM(COALESCE(nombre,'')))      IN ('METRO','METROS'))
      ORDER BY id LIMIT 1)::bigint    AS metro_id,
    0::numeric    AS iva_porcentaje,  -- 0 si no es responsable de IVA, 19 si lo es
    TRUE          AS iva_incluido;    -- TRUE: el precio del Excel ya trae el IVA

DO $$
BEGIN
    IF (SELECT empresa_id  FROM _p) IS NULL THEN RAISE EXCEPTION 'Falta empresa_id en el bloque PARAMETROS';  END IF;
    IF (SELECT sucursal_id FROM _p) IS NULL THEN RAISE EXCEPTION 'Falta sucursal_id en el bloque PARAMETROS'; END IF;
    IF (SELECT und_id      FROM _p) IS NULL THEN RAISE EXCEPTION 'No se encontro la unidad de medida UND/Unidad; crearla o poner el id a mano';   END IF;
    IF (SELECT metro_id    FROM _p) IS NULL THEN RAISE EXCEPTION 'No se encontro la unidad de medida METRO; crearla o poner el id a mano';        END IF;
    IF NOT EXISTS (SELECT 1 FROM empresa  WHERE id = (SELECT empresa_id  FROM _p)) THEN
        RAISE EXCEPTION 'No existe la empresa indicada';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM sucursal WHERE id = (SELECT sucursal_id FROM _p)
                                            AND empresa_id = (SELECT empresa_id FROM _p)) THEN
        RAISE EXCEPTION 'La sucursal no existe o no pertenece a la empresa indicada';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM unidad_medida WHERE id = (SELECT und_id   FROM _p)) THEN
        RAISE EXCEPTION 'No existe la unidad UND';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM unidad_medida WHERE id = (SELECT metro_id FROM _p)) THEN
        RAISE EXCEPTION 'No existe la unidad METRO';
    END IF;
END $$;

-- ---------------------------------------------------------------------
--  1. CATEGORIAS
-- ---------------------------------------------------------------------
CREATE TEMP TABLE _cat (nombre varchar(150)) ON COMMIT DROP;

SELECT p.empresa_id, c.nombre, p.iva_porcentaje, TRUE, NOW(), NOW()
  FROM _cat c CROSS JOIN _p p
 WHERE NOT EXISTS (
     SELECT 1 FROM categoria x
      WHERE x.empresa_id = p.empresa_id
        AND UPPER(TRIM(x.nombre)) = UPPER(TRIM(c.nombre))
        AND x.deleted_at IS NULL);

-- ---------------------------------------------------------------------
--  2. STAGING - las 1998 filas del Excel
-- ---------------------------------------------------------------------
CREATE TEMP TABLE _stage (
    sku         varchar(100),
    nombre      varchar(255),
    categoria   varchar(150),
    unidad      varchar(10),   -- UND | METRO
    costo       numeric(14,4),
    precio      numeric(14,4),
    cantidad    numeric(14,4),
    descripcion text
) ON COMMIT DROP;









CREATE UNIQUE INDEX _stage_sku_uq ON _stage (sku);

DO $$
DECLARE n int;
BEGIN
    SELECT COUNT(*) INTO n FROM _stage;
    IF n <> 1998 THEN
        RAISE EXCEPTION 'El staging quedo con % filas y se esperaban 1998', n;
    END IF;
END $$;

-- ---------------------------------------------------------------------
--  3. PRODUCTOS
-- ---------------------------------------------------------------------
    empresa_id, categoria_id, unidad_medida_base_id,
    sku, nombre, descripcion, tipo_producto,
    maneja_inventario, maneja_lotes, maneja_serial, permitir_stock_negativo,
    costo, precio, iva_porcentaje, iva_incluido, impoconsumo,
    activo, visible_en_pos, created_at, updated_at)
SELECT
    p.empresa_id,
    c.id,
    CASE WHEN s.unidad = 'METRO' THEN p.metro_id ELSE p.und_id END,
    s.sku, s.nombre, s.descripcion, 'ESTANDAR',
    TRUE, FALSE, FALSE, FALSE,
    s.costo, s.precio, p.iva_porcentaje, p.iva_incluido, 0,
    TRUE, TRUE, NOW(), NOW()
  FROM _stage s
  CROSS JOIN _p p
  JOIN categoria c
    ON c.empresa_id = p.empresa_id
   AND UPPER(TRIM(c.nombre)) = UPPER(TRIM(s.categoria))
   AND c.deleted_at IS NULL
 WHERE NOT EXISTS (
     SELECT 1 FROM producto x
      WHERE x.empresa_id = p.empresa_id
        AND x.sku = s.sku
        AND x.deleted_at IS NULL);

-- ---------------------------------------------------------------------
--  4. EXISTENCIAS
-- ---------------------------------------------------------------------
SELECT p.sucursal_id, pr.id, s.cantidad, 0, NOW()
  FROM _stage s
  CROSS JOIN _p p
  JOIN producto pr
    ON pr.empresa_id = p.empresa_id AND pr.sku = s.sku AND pr.deleted_at IS NULL
 WHERE NOT EXISTS (
     SELECT 1 FROM inventario i
      WHERE i.sucursal_id = p.sucursal_id AND i.producto_id = pr.id);

-- ---------------------------------------------------------------------
--  5. KARDEX - saldo inicial
--  Se registra como RECONTEO_AJUSTE_POSITIVO (entrada) de 0 a la
--  cantidad del Excel. La cantidad va en valor absoluto porque asi lo
--  guarda el reconteo; el sentido lo da saldo_nuevo - saldo_anterior.
-- ---------------------------------------------------------------------
    sucursal_id, producto_id, tipo_movimiento,
    cantidad, saldo_anterior, saldo_nuevo, costo_historico,
    referencia_origen, created_at)
SELECT p.sucursal_id, pr.id, 'RECONTEO_AJUSTE_POSITIVO',
       s.cantidad, 0, s.cantidad, s.costo,
       'MIGRACION_INICIAL_EXCEL', NOW()
  FROM _stage s
  CROSS JOIN _p p
  JOIN producto pr
    ON pr.empresa_id = p.empresa_id AND pr.sku = s.sku AND pr.deleted_at IS NULL
 WHERE s.cantidad > 0
   AND NOT EXISTS (
     SELECT 1 FROM movimiento_inventario m
      WHERE m.sucursal_id = p.sucursal_id
        AND m.producto_id = pr.id
        AND m.referencia_origen = 'MIGRACION_INICIAL_EXCEL');

-- ---------------------------------------------------------------------
--  6. VERIFICACION - revisar antes del COMMIT
-- ---------------------------------------------------------------------
SELECT 'categorias' AS que, COUNT(*) AS filas
  FROM categoria c CROSS JOIN _p p
 WHERE c.empresa_id = p.empresa_id AND c.deleted_at IS NULL
UNION ALL
SELECT 'productos', COUNT(*)
  FROM producto pr CROSS JOIN _p p
 WHERE pr.empresa_id = p.empresa_id AND pr.deleted_at IS NULL
UNION ALL
SELECT 'inventario', COUNT(*)
  FROM inventario i CROSS JOIN _p p
  JOIN producto pr ON pr.id = i.producto_id
 WHERE i.sucursal_id = p.sucursal_id AND pr.empresa_id = p.empresa_id
UNION ALL
SELECT 'kardex inicial', COUNT(*)
  FROM movimiento_inventario m CROSS JOIN _p p
 WHERE m.sucursal_id = p.sucursal_id AND m.referencia_origen = 'MIGRACION_INICIAL_EXCEL';

-- Debe dar: 1998 productos, 8 categorias, 1998 filas de inventario y
-- 1972 movimientos de kardex (los 26 productos en cero no generan movimiento).

-- Valor del inventario segun el Excel:
--   al costo   = 105,898,941.97
--   a la venta = 174,747,890.00
SELECT ROUND(SUM(i.stock_actual * pr.costo), 2)  AS valor_al_costo,
       ROUND(SUM(i.stock_actual * pr.precio), 2) AS valor_a_la_venta
  FROM inventario i CROSS JOIN _p p
  JOIN producto pr ON pr.id = i.producto_id
 WHERE i.sucursal_id = p.sucursal_id AND pr.empresa_id = p.empresa_id;

COMMIT;
-- Si algo no cuadra:  ROLLBACK;
